import sys

data = sys.stdin.read().split()
n, m, s, t = int(data[0]), int(data[1]), int(data[2]), int(data[3])
edges = []
p = 4
for _ in range(m):
    edges.append((int(data[p]), int(data[p + 1]), int(data[p + 2])))
    p += 3
INF = float('inf')
cur = {s: 0}
best = 0 if s == t else INF
for k in range(2 * n + 2):
    nxt = {}
    for (u, v, w) in edges:
        if u in cur:
            c = cur[u] + w + k
            if v not in nxt or c < nxt[v]:
                nxt[v] = c
    cur = nxt
    if t in cur and cur[t] < best:
        best = cur[t]
print(-1 if best == INF else best)

